const looksLikeUuid = (v) =>
  typeof v === 'string' &&
  /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$/.test(v.trim())

const sanitizeFilename = (value) =>
  String(value || "site-package")
    .replace(/[<>:"/\\|?\\*\x00-\x1F]/g, "-")
    .replace(/\\s+/g, " ")
    .trim()
    .slice(0, 120)

const BULK_ZIP_ID = '__all-site-packages__'

const packageZipName = (pkg) =>
  pkg?.packageName || `${pkg?.studyName || 'Study'} - ${pkg?.ethicsBoard || 'IRB'}`

const uniqueZipFolderName = (baseName, usedNames) => {
  const base = sanitizeFilename(baseName) || 'site-package'
  const seen = usedNames.get(base) || 0
  usedNames.set(base, seen + 1)
  return seen === 0 ? base : `${base}-${seen + 1}`
}

const extractExtension = (value) => {
  const raw = String(value || '')
  if (!raw) return ''
  try {
    const cleaned = raw.split('?')[0]
    const name = cleaned.split('/').pop() || cleaned
    const parts = name.split('.')
    if (parts.length < 2) return ''
    return String(parts.pop() || '').toLowerCase()
  } catch {
    return ''
  }
}

