const progressBarColor = (value) => {
  if (value >= 100) return 'bg-emerald-500'
  if (value >= 60) return 'bg-blue-500'
  if (value >= 30) return 'bg-amber-500'
  return 'bg-slate-400'
}

const isDraftStatus = (status) =>
  String(status || 'Draft').trim().toLowerCase() === 'draft'

const formatDate = (date) => {
  if (!date) return '—'
  try {
    const d = new Date(date)
    if (isNaN(d.getTime())) return '—'
    return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })
  } catch {
    return '—'
  }
}

const formatDateTime = (date) => {
  if (!date) return '—'
  try {
    const d = new Date(date)
    if (isNaN(d.getTime())) return '—'
    const now = new Date()
    const diffMs = now - d
    const diffDays = Math.floor(diffMs / (1000 * 60 * 60 * 24))
    if (diffDays === 0) return 'Today'
    if (diffDays === 1) return 'Yesterday'
    if (diffDays < 7) return `${diffDays}d ago`
    return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: d.getFullYear() })
  } catch {
    return '—'
  }
}

/**
 * Navbar stores study as UUID (`study.id`) and site as external code (`site.site_id`).
 * List API returns populated study/site with `_id` (UUID) plus `studyId` / `siteId` strings.
 * Match if the header selection equals any of those identifiers so rows are not hidden incorrectly.
 */
function pkgStudyKeySet(pkg) {
  const s = pkg?.study
  const out = new Set()
  if (s && typeof s === 'object') {
    ;[s._id, s.id, s.studyId].forEach((v) => {
      if (v != null && String(v).trim()) out.add(String(v).trim())
    })
  } else if (typeof s === 'string' && s.trim()) {
    out.add(s.trim())
  }
  return out
}

function pkgSiteKeySet(pkg) {
  const x = pkg?.site
  const out = new Set()
  if (x && typeof x === 'object') {
    ;[x._id, x.id, x.siteId].forEach((v) => {
      if (v != null && String(v).trim()) out.add(String(v).trim())
    })
  } else if (typeof x === 'string' && x.trim()) {
    out.add(x.trim())
  }
  return out
}

function selectionMatchesPkgWorkspace(pkg, selectedStudy, selectedSite) {
  if (!selectedStudy || !selectedSite) return true
  return (
    pkgStudyKeySet(pkg).has(String(selectedStudy)) &&
    pkgSiteKeySet(pkg).has(String(selectedSite))
  )
}

